def build_vocab_item(
    item_id: str,
    concept_key: str,
    topic: str,
    level: str,
    native_text: str,
    romanized: str,
    pronunciation_guide: str,
    example_native: str,
    example_romanized: str,
    example_en: str,
    grammar_note: str,
) -> Dict[str, Any]:
    meanings = dict(CONCEPT_TRANSLATIONS.get(concept_key, {"en": example_en}))
    return {
        "id": item_id,
        "conceptKey": concept_key,
        "topic": topic,
        "level": level,
        "nativeText": native_text,
        "romanized": romanized,
        "pronunciationGuide": pronunciation_guide,
        "meanings": meanings,
        "exampleNative": example_native,
        "exampleRomanized": example_romanized,
        "exampleMeaning": example_en,
        "grammarNote": grammar_note,
    }


def make_curriculum(lang_code: str, items_spec: List[tuple]) -> List[Dict[str, Any]]:
    result = []
    combined_specs = list(items_spec) + ADDITIONAL_TOPIC_SPECS.get(lang_code, [])
    for idx, spec in enumerate(combined_specs, start=1):
        (
            concept_key,
            topic,
            level,
            native_text,
            romanized,
            pron_guide,
            ex_native,
            ex_roman,
            ex_en,
            grammar_note,
        ) = spec
        result.append(
            build_vocab_item(
                f"{lang_code}_w{idx}",
                concept_key,
                topic,
                level,
                native_text,
                romanized,
                pron_guide,
                ex_native,
                ex_roman,
                ex_en,
                grammar_note,
            )
        )
    return result



