def get_language_by_code(code: str) -> Dict[str, Any]:
    for lang in LANGUAGES_REGISTRY:
        if lang["code"] == code:
            return lang
    return LANGUAGES_REGISTRY[0]


def localize_vocab_item(item: Dict[str, Any], explanation_lang: str) -> Dict[str, Any]:
    """Return a copy of the vocabulary item with `meaning` resolved in the chosen explanation language."""
    meanings_map = item.get("meanings", {})
    chosen_meaning = meanings_map.get(explanation_lang) or meanings_map.get("en") or item.get("exampleMeaning", "")
    # If explanation_lang is not English and we have a localized meaning, show both for clarity
    en_meaning = meanings_map.get("en", item.get("exampleMeaning", ""))
    if explanation_lang != "en" and chosen_meaning != en_meaning:
        display_meaning = f"{chosen_meaning} ({en_meaning})"
    else:
        display_meaning = chosen_meaning

    return {
        **item,
        "meaning": display_meaning,
        "explanationLang": explanation_lang,
    }
